\Chapter[SUM AND DIFFERENCE OF ANGLES]
{X.}{THE SINE AND COSINE OF THE SUM AND DIFFERENCE
OF TWO ANGLES.}

\Paragraph[\No{1}]{To find the sine and cosine of the sum of two angles.}

\begin{wrapfigure}[9]{r}{2.25in}
  \Input[2.25in]{053a}
\end{wrapfigure}
Let $C$ be the centre of a circle of which the radius
$CA = R$.

Let the circular measure of
$ACB = \theta$, and of $BCD = \phi$.

Then $\theta + \phi$ is the circular
measure of~$ACD$.

Draw $DE$, $DF$ perpendicular
to $CA$,~$CB$.

Then
\begin{align*}
&&DE &= R \sin (\theta + \phi); & CE &= R \cos (\theta + \phi); &&\\
&&DF &= R \sin \phi;            & CF &= R \cos \phi. &&
\end{align*}

But $DE$ is the projection of the broken line $CFD$ on~$DE$;
therefore
\begin{gather*}
\begin{aligned}
DE &= \text{projection of } CF + \text{projection of } FD \\
   &= CF \cos \left(\frac{\pi}{2} - \theta\right) + FD \cos\theta \\
   &= CF \sin\theta + FD \cos\theta,                  \\
\end{aligned} \\
\begin{aligned}
\text{i.e.\ }
R \sin (\theta + \phi) &= R \cos\phi \sin\theta + R \sin\phi \cos\theta, \\
\text{or\ }
\sin (\theta + \phi) &= \sin\theta \cos\phi + \cos\theta \sin\phi.
\end{aligned}
\end{gather*}

Again, $CE$ is the projection of the broken line $CFD$
on~$CA$,
\begin{gather*}
\begin{aligned}
\therefore CE &= \text{projection of } CF + \text{projection of } FD \\
  &= CF \cos\theta + FD \cos \left(\frac{\pi}{2} + \theta\right) \\
  &= CF \cos\theta - FD \sin\theta;
\end{aligned} \\
\begin{aligned}
\text{i.e.\ }
R \cos (\theta + \phi) &= R \cos\phi \cos\theta - R \sin\phi \sin\theta, \\
\text{or }
\cos (\theta + \phi)   &= \cos\theta \cos\phi - \sin\theta \sin\phi.
\end{aligned}
\end{gather*}

\Paragraph[\No{2}]{To find the sine and cosine of the difference of two
angles.}

\begin{wrapfigure}[9]{r}{2.25in}
  \Input[2.25in]{054a}
\end{wrapfigure}
Let
\begin{align*}
\theta &= \text{circular measure of $ACB$}, \\
\phi   &= \text{\PadTxt{circular measure}{\dotfill} of $BCD$.}
\end{align*}

Then $\theta - \phi =$ circular measure
of $ACD$.

Draw $DE$, $DF$ perpendicular
to $CA$,~$CB$.

Then

\begin{align*}
&&DE &= R \sin (\theta - \phi); &&&&\\
&&CE &= R \cos (\theta - \phi); &&&&\\
&&CF &= R \cos \phi; & FD &= R \sin \phi.&&
\end{align*}


But $DE$ is the projection of $CFD$ on~$DE$
\begin{gather*}
\begin{aligned}
  &= \text{projection of } CF + \text{projection of } FD \\
  &= CF \cos \left(\frac{\pi}{2} - \theta\right) + FD \cos (\pi - \theta) \\
  &= CF \sin \theta - FD \cos \theta;
\end{aligned} \\
\begin{aligned}
\text{i.e.\ }
R \sin (\theta - \phi) &= R \cos\phi \sin\theta - R \sin\phi \cos\theta, \\
\text{or }
\sin (\theta - \phi) &= \sin\theta \cos\phi - \cos\theta \sin\phi.
\end{aligned}
\end{gather*}

Again, $CE$ is the projection of $CFD$ on~$CA$
\begin{gather*}
\begin{aligned}
  &= \text{projection of } CF + \text{projection of } FD \\
  &= CF \cos \theta + FD \cos \left(\theta - \frac{\pi}{2}\right) \\
  &= CF \cos \theta + FD \sin \theta;
\end{aligned} \\
\begin{aligned}
\text{i.e.\ }
R \cos (\theta - \phi) &= R \cos\phi \cos\theta + R \sin\phi \sin\theta, \\
\text{or }
\cos (\theta - \phi) &= \cos\phi \cos\theta + \sin\phi \sin\theta.
\end{aligned}
\end{gather*}

The four expressions for $\sin (\theta ± \phi)$ and $\cos (\theta ± \phi)$ are
true for all values of $\theta$~and~$\phi$, though the diagrams suppose
the angles all acute. They form the fundamental formulæ
of Analytical Trigonometry.


\Appendix{(Note to \Pageref{10}.)}

To shew that, when the difference between $R$~and~$r$ is
small, the limit of each radius is very nearly $= \dfrac{1}{3}(r + 2R)$.

Let $r_1, r_2, \dots$ be the radii of the circles inscribed in the
successive polygons, and $R_1, R_2, \dots$ of those circumscribed
about the same. Let also the limit of both be called~$r_\infty$.

Let $R - r = 2\delta$; then $r_1 = \dfrac{R + r}{2} = r + \delta = R - \delta$.

Let
\begin{align*}
  r_2 &= r_1 + \delta_1;\quad r_3 = r_2 + \delta_2;\quad \text{\&c.} \\
  \intertext{\indent Then}
  r_\infty &= r + \delta + \delta_1 + \delta_2 + \text{\&c.\ \textit{ad inf.}} \\
  \intertext{\indent Also}
  R &= r + 2\delta;\quad R_1 = r_1 + 2\delta_1;\quad \text{\&c.} \\
  \intertext{and}
  R &= r_1 + \delta;\quad R_1 = r_2 + \delta_1;\quad \text{\&c.} \\
  \intertext{\indent But}
  R_1^2 &= r_1R;\quad \text{or } (r_1 + 2\delta_1)^2 = r_1(r_1 + \delta); \\
\end{align*}
\begin{gather*}
\therefore 4r_1\delta_1 + 4\delta_1^2 = r_1\delta; \\

\therefore \delta_1
  = \frac{\delta}{4} - \frac{\delta_1^2}{r_1}
  < \frac{\delta}{4} > \frac{\delta}{4} - \frac{\delta_1^2}{r}; \\
\therefore \delta_1
  < \frac{\delta}{4}
  > \frac{\delta}{4} - \frac{1}{r}\left(\frac{\delta}{4}\right)^2. \\
\intertext{\indent Similarly}
\delta_2
  < \frac{\delta_1}{4}
  > \frac{\delta_1}{4} - \frac{1}{r}\left(\frac{\delta_1}{4}\right)^2
  > \frac{\delta_1}{4} - \frac{1}{r}\left(\frac{\delta}{4^2}\right)^2, \\
\delta_3
  < \frac{\delta_2}{4}
  > \frac{\delta_2}{4} - \frac{1}{r}\left(\frac{\delta_2}{4}\right)^2
  > \frac{\delta_2}{4} - \frac{1}{r}\left(\frac{\delta}{4^3}\right)^2, \\
\delta_4
  < \frac{\delta_3}{4}
  > \frac{\delta_3}{4} - \frac{1}{r}\left(\frac{\delta_3}{4}\right)^2
  > \frac{\delta_3}{4} - \frac{1}{r}\left(\frac{\delta}{4^4}\right)^2, \\
\text{\&c.\qquad\qquad\qquad \&c.}
 \\ 
\therefore \delta + \delta_1 + \delta_2 + \dots
\text{ \textit{ad inf.}}
< \delta + \frac{\delta}{4} + \frac{\delta_1}{4} + \frac{\delta_2}{4} + \dots
\text{ \textit{ad inf.}}
\end{gather*}
and
\[
\therefore \frac{3}{4}\{\delta + \delta_1 + \delta_2 + \dots
\text{ \textit{ad inf.}}\} < \delta,
\]
or
\[
\delta + \delta_1 + \delta_2 + \dots < \frac{4}{3}\, \delta.
\]

And
\begin{multline*}
\delta + \delta_1 + \delta_2 + \dots
  > \delta + \frac{\delta}{4} + \frac{\delta_1}{4} +
  \text{ \&c.\ \textit{ad inf.}} \\
- \frac{1}{r} \left\{
  \left(\frac{\delta}{4}\right)^2
  + \left(\frac{\delta}{4^2}\right)^2 + \dots
  \text{ \textit{ad inf.}}\right\};
\end{multline*}
\begin{gather*}
\therefore \frac{3}{4}(\delta + \delta_1 + \delta_2 + \dots)
  > \delta - \frac{\delta^2}{16r} × \frac{16}{15}
  > \delta - \frac{\delta^2}{15r}; \\
\therefore \delta + \delta_1 + \delta_2 + \dots \text{ \textit{ad inf.}}
  > \frac{4}{3}\, \delta - \frac{4}{45}· \frac{\delta^2}{r};
\end{gather*}

\begin{align*}
\therefore r_\infty
  &< r + \frac{4}{3} \delta &
  &> r + \frac{4}{3}\, \delta - \frac{4}{45}\, \frac{\delta^2}{r}, \\
  &< \frac{1}{3} (r + 2R)   &
  &> \frac{1}{3} (r + 2R) - \frac{(R - r)^2}{45r}.
\end{align*}


So that when, as in the text, $R - r < .00003$ the error
in taking the ultimate radius $= \dfrac{1}{3}(r + 2R)$ is $< \dfrac{.0000000009}{45r}$
which does not affect the tenth decimal place.
